-- else an existing multi-word vehicles.make used by >=2 vehicles outside this run. Uncertain titles are flagged, not changed.
create table if not exists public.backup_rm_makefix_v1_20261024 (vehicle_id uuid primary key, old_make text, old_model text, old_canonical_make_id uuid,
  old_make_source text, old_model_source text, new_make text, new_model text, ref text, title text, run_id text not null, fixed_at timestamptz not null default now());
alter table public.backup_rm_makefix_v1_20261024 enable row level security;
