), g as (
  select s.*, v.canonical_make_id ocm, v.make_source oms, v.model_source omo from s
  join public.vehicles v on v.id=s.vehicle_id and v.make is not distinct from s.old_make and v.model is not distinct from s.old_model
  join public.vehicle_events e on e.vehicle_id=v.id and e.extraction_run_id='rm_ingest_v1_20261024' and e.metadata->>'title'=s.title
), b as (
  insert into public.backup_rm_makefix_v1_20261024 (vehicle_id,old_make,old_model,old_canonical_make_id,old_make_source,old_model_source,new_make,new_model,ref,title,run_id)
  select vehicle_id,old_make,old_model,ocm,oms,omo,new_make,new_model,ref,title,'rm_makefix_v1_20261024' from g on conflict (vehicle_id) do nothing returning vehicle_id
)
update public.vehicles v set make=g.new_make, model=g.new_model, canonical_make_id=coalesce(g.cm_id, v.canonical_make_id),
  make_source='rm_makefix_v1_20261024: RM lot title; '||g.ref, model_source='rm_makefix_v1_20261024: RM lot title after make', updated_at=now()
from g join b on b.vehicle_id=g.vehicle_id where v.id=g.vehicle_id;
